workshop_times = {'Casting': casting_time, 'Milling': milling_time, 'Finishing': finishing_time, 'Assembly': assembly_time, 'QA & Packaging': qa_packaging_time}
for arr in [unit_price, casting_time, milling_time, finishing_time, assembly_time, qa_packaging_time]:
    if len(arr) != len(components):
        raise ValueError('Coefficient vector length does not match number of components')
m = gp.Model('factory_production')
m.Params.MIPGap = 0.0001
x_vars = m.addVars(components, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((unit_price[i] * x_vars[components[i]] for i in range(len(components)))), GRB.MAXIMIZE)
for (w, cap) in workshop_caps.items():
    times = workshop_times[w]
    m.addConstr(gp.quicksum((times[i] * x_vars[components[i]] for i in range(len(components)))) <= cap, name=f'{w[:3].lower()}_cap')
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in x_vars.values():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')